<script setup lang="ts">
definePageMeta({ layout: 'admin' })
const { data, pending, error, refresh } = await useFetch<any>('/api/admin/shipments', { server: false, retry: false })
const { data: orderData, refresh: refreshOrders } = await useFetch<any>('/api/admin/orders', { server: false, retry: false })
const toast = useToast()
const search = ref('')
const statusFilter = ref('all')
const modalOpen = ref(false)
const saving = ref(false)
const formError = ref('')
const form = reactive({ orderId: 0, carrier: 'Kerry Express', trackingNo: '', note: '' })
const shipments = computed(() => {
  let items = [...(data.value?.shipments || [])]
  if (statusFilter.value !== 'all') items = items.filter((item: any) => item.status === statusFilter.value)
  const term = search.value.trim().toLowerCase()
  if (term) items = items.filter((item: any) => `${item.orderNo} ${item.customerName} ${item.trackingNo} ${item.carrier}`.toLowerCase().includes(term))
  return items
})
const eligibleOrders = computed(() => (orderData.value?.orders || []).filter((order: any) => order.status === 'processing' && !order.shipment))
const counts = computed(() => ({ all: data.value?.shipments?.length || 0, in_transit: (data.value?.shipments || []).filter((item: any) => item.status === 'in_transit').length, delivered: (data.value?.shipments || []).filter((item: any) => item.status === 'delivered').length, returned: (data.value?.shipments || []).filter((item: any) => item.status === 'returned').length }))
const countForStatus = (status: string) => counts.value[status as keyof typeof counts.value] || 0
function openCreate() { const order = eligibleOrders.value[0]; formError.value = ''; form.orderId = order?.id || 0; form.carrier = order?.shippingMethod === 'company_truck' ? 'รถบริษัทอัญชลี' : 'Kerry Express'; form.trackingNo = ''; form.note = ''; modalOpen.value = true }
async function createShipment() { saving.value = true; formError.value = ''; try { await $fetch('/api/admin/shipments', { method: 'POST', body: form }); modalOpen.value = false; await Promise.all([refresh(), refreshOrders()]); toast.show('สร้างรายการจัดส่งและบันทึกเลขพัสดุแล้ว') } catch (err: any) { formError.value = err?.data?.statusMessage || 'บันทึกการจัดส่งไม่สำเร็จ' } finally { saving.value = false } }
async function updateStatus(shipment: any, status: string) { saving.value = true; try { await $fetch(`/api/admin/shipments/${shipment.id}`, { method: 'PATCH', body: { status } }); await Promise.all([refresh(), refreshOrders()]); toast.show(status === 'delivered' ? 'อัปเดตว่าจัดส่งสำเร็จแล้ว' : 'อัปเดตสถานะพัสดุแล้ว') } catch (err: any) { toast.show(err?.data?.statusMessage || 'อัปเดตสถานะไม่สำเร็จ', 'error') } finally { saving.value = false } }
async function copyTracking(code: string) { try { await navigator.clipboard.writeText(code); toast.show('คัดลอกเลขพัสดุแล้ว') } catch { toast.show(code, 'info') } }
</script>

<template>
  <div class="admin-page-wrap"><div class="admin-page-heading"><div><span class="section-kicker">SHIP, TRACK, DELIVER</span><h1>การจัดส่ง <span class="heading-count">{{ data?.shipments?.length || 0 }}</span></h1><p>จัดการเลขพัสดุและติดตามสถานะการส่งถึงลูกค้า</p></div><button class="button button-primary" :disabled="!eligibleOrders.length" @click="openCreate"><AppIcon name="plus" :size="17"/> บันทึกเลขพัสดุ <span v-if="eligibleOrders.length" class="button-count">{{ eligibleOrders.length }}</span></button></div>
    <section class="stat-grid compact-stat-grid"><article class="mini-stat-card"><span class="mini-stat-icon mini-purple"><AppIcon name="truck" :size="18"/></span><span><small>รายการจัดส่งทั้งหมด</small><strong>{{ counts.all }} <i>รายการ</i></strong></span></article><article class="mini-stat-card"><span class="mini-stat-icon mini-blue"><AppIcon name="clock" :size="17"/></span><span><small>กำลังเดินทาง</small><strong>{{ counts.in_transit }} <i>รายการ</i></strong></span></article><article class="mini-stat-card"><span class="mini-stat-icon mini-green"><AppIcon name="package-check" :size="17"/></span><span><small>จัดส่งสำเร็จ</small><strong>{{ counts.delivered }} <i>รายการ</i></strong></span></article></section>
    <section class="admin-panel shipments-panel"><div class="shipment-toolbar"><div class="stock-filters"><button v-for="tab in [{id:'all',label:'ทั้งหมด'}, {id:'in_transit',label:'กำลังจัดส่ง'}, {id:'delivered',label:'สำเร็จ'}, {id:'returned',label:'ตีกลับ'}]" :key="tab.id" class="filter-tab" :class="{ active: statusFilter === tab.id }" @click="statusFilter = tab.id">{{ tab.label }}<span>{{ countForStatus(tab.id) }}</span></button></div><label class="admin-search"><AppIcon name="search" :size="17"/><input v-model="search" type="search" placeholder="ค้นหาเลขพัสดุ / ออเดอร์..."/></label></div><div v-if="pending" class="admin-loading-card"><span class="loading-spinner"/> กำลังโหลดข้อมูลจัดส่ง...</div><div v-else-if="error" class="admin-error-card"><AppIcon name="alert" :size="20"/> โหลดข้อมูลจัดส่งไม่สำเร็จ <button class="button button-outline" @click="refresh()">ลองอีกครั้ง</button></div><div v-else-if="shipments.length" class="table-scroll"><table class="admin-table shipments-table"><thead><tr><th>ผู้รับ</th><th>ขนส่ง / เลขพัสดุ</th><th>เลขคำสั่งซื้อ</th><th>วันที่ส่ง</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody><tr v-for="shipment in shipments" :key="shipment.id"><td><div class="table-customer"><span class="customer-avatar-small"><AppIcon name="user" :size="14"/></span><span>{{ shipment.customerName }}<small>{{ shipment.customerPhone }}</small></span></div></td><td><div class="tracking-cell"><strong>{{ shipment.carrier }}</strong><button @click="copyTracking(shipment.trackingNo)">{{ shipment.trackingNo }} <AppIcon name="copy" :size="13"/></button></div></td><td><NuxtLink class="table-order-no" to="/admin/orders">{{ shipment.orderNo }}</NuxtLink></td><td>{{ formatDate(shipment.shippedAt) }}</td><td><span class="status-pill" :class="`shipment-${shipment.status}`">{{ shipmentStatusLabels[shipment.status] || shipment.status }}</span></td><td><div v-if="shipment.status === 'in_transit'" class="row-actions"><button class="button button-small button-outline" :disabled="saving" @click="updateStatus(shipment, 'delivered')"><AppIcon name="check" :size="14"/> ส่งสำเร็จ</button><button class="table-action-button" title="ทำเครื่องหมายพัสดุตีกลับ" :disabled="saving" @click="updateStatus(shipment, 'returned')"><AppIcon name="reset" :size="15"/></button></div><span v-else class="shipment-date-done">{{ shipment.status === 'delivered' ? formatDate(shipment.deliveredAt || shipment.shippedAt) : 'ปิดรายการ' }}</span></td></tr></tbody></table></div><div v-else class="panel-empty"><AppIcon name="truck" :size="26"/><span>ยังไม่มีรายการจัดส่งในหมวดนี้</span><button v-if="eligibleOrders.length" class="text-link" @click="openCreate">บันทึกเลขพัสดุรายการแรก</button></div><div class="table-footer"><span>แสดง {{ shipments.length }} จาก {{ data?.shipments?.length || 0 }} รายการ</span><NuxtLink class="panel-action" to="/track">เปิดหน้าติดตามพัสดุ <AppIcon name="external" :size="14"/></NuxtLink></div></section>
    <section class="shipping-tip"><span class="shipping-tip-icon"><AppIcon name="sparkles" :size="19"/></span><span><strong>แจ้งเลขพัสดุให้ลูกค้าได้ทันที</strong><small>เมื่อลงทะเบียนเลขพัสดุแล้ว ลูกค้าสามารถตรวจสอบสถานะได้จากหน้า “ติดตามสินค้า” บนเว็บไซต์</small></span><NuxtLink to="/track" class="button button-small button-outline">ดูหน้าติดตาม <AppIcon name="arrow-right" :size="14"/></NuxtLink></section>
    <AdminModal v-model="modalOpen" title="บันทึกเลขพัสดุ" subtitle="สร้างรายการจัดส่งสำหรับคำสั่งซื้อที่กำลังเตรียมสินค้า"><form class="admin-form" @submit.prevent="createShipment"><label class="field-label">คำสั่งซื้อ <span>*</span><select v-model.number="form.orderId" required><option v-for="order in eligibleOrders" :key="order.id" :value="order.id">{{ order.orderNo }} — {{ order.shippingName || order.customer?.name }} (฿{{ formatBaht(order.total) }})</option></select><small v-if="!eligibleOrders.length" class="field-hint">ไม่มีคำสั่งซื้อที่รอจัดส่ง</small></label><label class="field-label">บริษัทขนส่ง <span>*</span><select v-model="form.carrier"><option>รถบริษัทอัญชลี</option><option>Kerry Express</option><option>ไปรษณีย์ไทย</option><option>Flash Express</option><option>J&T Express</option><option>ขนส่งอื่น ๆ</option></select></label><label class="field-label">เลขพัสดุ / ข้อมูลนัดหมาย <span v-if="form.carrier !== 'รถบริษัทอัญชลี'">*</span><input v-model="form.trackingNo" :required="form.carrier !== 'รถบริษัทอัญชลี'" maxlength="100" placeholder="กรอกเลข Tracking หรือข้อมูลนัดหมาย"><small v-if="form.carrier === 'รถบริษัทอัญชลี'">เว้นว่างได้ ระบบจะแจ้งให้ติดต่อนัดหมายกับร้าน</small></label><label class="field-label">หมายเหตุ<textarea v-model="form.note" rows="2" maxlength="400" placeholder="ข้อมูลเพิ่มเติม (ไม่บังคับ)"></textarea></label><p v-if="formError" class="form-error"><AppIcon name="alert" :size="16"/> {{ formError }}</p><div class="modal-actions"><button type="button" class="button button-outline" @click="modalOpen = false">ยกเลิก</button><button type="submit" class="button button-primary" :disabled="saving || !eligibleOrders.length"><AppIcon :name="saving ? 'loader' : 'save'" :size="16" :class="{ spinning: saving }"/> {{ saving ? 'กำลังบันทึก...' : 'ยืนยันการจัดส่ง' }}</button></div></form></AdminModal>
  </div>
</template>
